@page "/notepad"
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject IJSRuntime JS

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<textarea class="form-control mb-3" rows="12" @bind="content" @bind:event="oninput"></textarea>

<div class="d-flex align-items-center gap-2 mb-3">
    <button class="btn btn-primary" @onclick="SaveNowAsync">Save now</button>
    <button class="btn btn-outline-danger" @onclick="ClearAsync">Clear</button>
    @if (lastSavedDisplay is not null)
    {
        <span class="text-muted ms-2">Last saved at @lastSavedDisplay</span>
    }
</div>

@code {
    private string content = string.Empty;
    private string? lastSavedDisplay;
    private string lastSavedContent = string.Empty;
    private IJSObjectReference? module;
    private System.Timers.Timer? autoSaveTimer;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (!firstRender) return;

        module = await JS.InvokeAsync<IJSObjectReference>(
            "import", "./Components/Pages/Notepad.razor.js");

        var saved = await module.InvokeAsync<string?>("load");
        if (saved is not null)
        {
            content = saved;
            lastSavedContent = saved;
            StateHasChanged();
        }

        autoSaveTimer = new System.Timers.Timer(30_000);
        autoSaveTimer.Elapsed += async (_, _) => await InvokeAsync(AutoSaveAsync);
        autoSaveTimer.Start();
    }

    private bool HasUnsavedChanges => content != lastSavedContent;

    private async Task AutoSaveAsync()
    {
        if (!HasUnsavedChanges) return;
        await SaveAsync();
    }

    private async Task SaveNowAsync()
    {
        await SaveAsync();
    }

    private async Task SaveAsync()
    {
        if (module is null) return;

        await module.InvokeVoidAsync("save", content);
        lastSavedContent = content;
        lastSavedDisplay = DateTime.Now.ToString("HH:mm:ss");
        await module.InvokeVoidAsync("setDirty", false);
        StateHasChanged();
    }

    private async Task ClearAsync()
    {
        if (module is null) return;

        content = string.Empty;
        lastSavedContent = string.Empty;
        lastSavedDisplay = null;
        await module.InvokeVoidAsync("clear");
        await module.InvokeVoidAsync("setDirty", false);
    }

    // Keep the JS beforeunload guard in sync whenever the content changes
    protected override async Task OnAfterRenderAsync()
    {
        if (module is not null)
        {
            await module.InvokeVoidAsync("setDirty", HasUnsavedChanges);
        }
    }

    public async ValueTask DisposeAsync()
    {
        autoSaveTimer?.Stop();
        autoSaveTimer?.Dispose();

        if (module is not null)
        {
            await module.InvokeVoidAsync("setDirty", false);
            await module.DisposeAsync();
        }
    }
}

const STORAGE_KEY = "notepad-content";

function onBeforeUnload(e) {
    e.preventDefault();
}

export function save(content) {
    localStorage.setItem(STORAGE_KEY, content);
}

export function load() {
    return localStorage.getItem(STORAGE_KEY);
}

export function clear() {
    localStorage.removeItem(STORAGE_KEY);
}

export function setDirty(dirty) {
    if (dirty) {
        window.addEventListener("beforeunload", onBeforeUnload);
    } else {
        window.removeEventListener("beforeunload", onBeforeUnload);
    }
}

